pub fn is_prime(n: i8) -> bool {
    // By definition, primes are integers >= 2.
    if n < 2 {
        return false;
    }

    // Try every possible divisor from 2 up to n-1.
    let mut divisor: i8 = 2;
    while divisor < n {
        // If we find a divisor, n is not prime.
        if n % divisor == 0 {
            return false;
        }
        divisor += 1;
    }

    // If no divisors were found, n is prime.
    true
}

